const InvoiceLineItemSchema = z
  .object({
    cloudProvider: z
      .enum(['AWS', 'GCP', 'AZURE', 'ATLAS'])
      .exactOptional()
      .openapi({
        description:
          "Code identifying the cloud provider this line item's usage is attributed to. Values map as follows: AWS is Amazon Web Services, GCP is Google Cloud, AZURE is Microsoft Azure, and ATLAS is other Atlas usage not tied to a specific cloud provider.",
        readOnly: true,
      }),
    clusterName: z
      .string()
      .regex(/^[a-zA-Z0-9][a-zA-Z0-9-]*$/)
      .exactOptional()
      .openapi({
        description: 'Human-readable label that identifies the cluster that incurred the charge.',
        readOnly: true,
      }),
    created: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'Date and time when MongoDB Cloud created this line item. This parameter expresses its value in the ISO 8601 timestamp format in UTC.',
        readOnly: true,
      }),
    discountCents: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          'Sum by which MongoDB discounted this line item. MongoDB Cloud expresses this value in cents (100ths of one US Dollar). The resource returns this parameter when a discount applies.',
        readOnly: true,
      }),
    endDate: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'Date and time when when MongoDB Cloud finished charging for this line item. This parameter expresses its value in the ISO 8601 timestamp format in UTC.',
        readOnly: true,
      }),
    groupId: z
      .string()
      .regex(/^([a-f0-9]{24})$/)
      .exactOptional()
      .openapi({
        description:
          'Unique 24-hexadecimal digit string that identifies the project associated to this line item.',
        example: '32b6e34b3d91647abb20e7b8',
        readOnly: true,
      }),
    groupName: z
      .string()
      .exactOptional()
      .openapi({ description: 'Human-readable label that identifies the project.' }),
    note: z
      .string()
      .exactOptional()
      .openapi({ description: 'Comment that applies to this line item.', readOnly: true }),
    percentDiscount: z
      .float32()
      .exactOptional()
      .openapi({
        description:
          'Percentage by which MongoDB discounted this line item. The resource returns this parameter when a discount applies.',
        readOnly: true,
      }),
    quantity: z
      .float64()
      .exactOptional()
      .openapi({
        description:
          'Number of units included for the line item. These can be expressions of storage (GB), time (hours), or other units.',
        readOnly: true,
      }),
    sku: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Human-readable description of the service that this line item provided. This Stock Keeping Unit (SKU) could be the instance type, a support charge, advanced security, or another service.',
        externalDocs: {
          description: 'To see how to list all possible values, click here.',
          url: 'https://www.mongodb.com/docs/atlas/reference/api-resources-spec/v2/#tag/Invoices/operation/listSkus',
        },
        readOnly: true,
      }),
    startDate: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'Date and time when MongoDB Cloud began charging for this line item. This parameter expresses its value in the ISO 8601 timestamp format in UTC.',
        readOnly: true,
      }),
    stitchAppName: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Human-readable label that identifies the Atlas App Services application associated with this line item.',
        externalDocs: {
          description: 'Create a new Atlas App Service',
          url: 'https://www.mongodb.com/docs/atlas/app-services/manage-apps/create/create-with-ui/',
        },
        readOnly: true,
      }),
    tags: z
      .record(
        z.string(),
        z
          .array(
            z
              .string()
              .openapi({
                description:
                  'A map of key-value pairs corresponding to the tags associated with the line item resource.',
                readOnly: true,
              }),
          )
          .openapi({
            description:
              'A map of key-value pairs corresponding to the tags associated with the line item resource.',
            readOnly: true,
          }),
      )
      .exactOptional()
      .openapi({
        description:
          'A map of key-value pairs corresponding to the tags associated with the line item resource.',
        readOnly: true,
      }),
    tierLowerBound: z
      .float64()
      .exactOptional()
      .openapi({
        description:
          'Lower bound for usage amount range in current SKU tier. \n\n**NOTE**: `lineItems[n].tierLowerBound` appears only if your `lineItems[n].sku` is tiered.',
        readOnly: true,
      }),
    tierUpperBound: z
      .float64()
      .exactOptional()
      .openapi({
        description:
          'Upper bound for usage amount range in current SKU tier. \n\n**NOTE**: `lineItems[n].tierUpperBound` appears only if your `lineItems[n].sku` is tiered.',
        readOnly: true,
      }),
    totalPriceCents: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          'Sum of the cost set for this line item. MongoDB Cloud expresses this value in cents (100ths of one US Dollar) and calculates this value as `unitPriceDollars` * `quantity` * 100.',
        readOnly: true,
      }),
    unit: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Element used to express what **quantity** this line item measures. This value can be elements of time, storage capacity, and the like.',
        readOnly: true,
      }),
    unitPriceDollars: z
      .float64()
      .exactOptional()
      .openapi({
        description: 'Value per **unit** for this line item expressed in US Dollars.',
        readOnly: true,
      }),
  })
  .openapi({
    description: 'One service included in this invoice.',
    title: 'Line Item',
    required: [],
  })
  .openapi('InvoiceLineItem')

const BillingPaymentSchema = z
  .object({
    amountBilledCents: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          'Sum of services that the specified organization consumed in the period covered in this invoice. This parameter expresses its value in cents (100ths of one US Dollar).',
        readOnly: true,
      }),
    amountPaidCents: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          'Sum that the specified organization paid toward the associated invoice. This parameter expresses its value in cents (100ths of one US Dollar).',
        readOnly: true,
      }),
    created: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'Date and time when the customer made this payment attempt. This parameter expresses its value in the ISO 8601 timestamp format in UTC.',
        readOnly: true,
      }),
    currency: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The currency in which payment was paid. This parameter expresses its value in 3-letter ISO 4217 currency code.',
        readOnly: true,
      }),
    id: z
      .string()
      .regex(/^([a-f0-9]{24})$/)
      .exactOptional()
      .openapi({
        description:
          'Unique 24-hexadecimal digit string that identifies this payment toward the associated invoice.',
        example: '32b6e34b3d91647abb20e7b8',
        readOnly: true,
      }),
    salesTaxCents: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          'Sum of sales tax applied to this invoice. This parameter expresses its value in cents (100ths of one US Dollar).',
        readOnly: true,
      }),
    statusName: z
      .enum([
        'NEW',
        'FORGIVEN',
        'FAILED',
        'PAID',
        'PARTIAL_PAID',
        'CANCELLED',
        'INVOICED',
        'FAILED_AUTHENTICATION',
        'PROCESSING',
        'PENDING_REVERSAL',
        'REFUNDED',
      ])
      .exactOptional()
      .openapi({
        description:
          "Phase of payment processing for the associated invoice when you made this request. These phases include:\n\n- `CANCELLED`: Customer or MongoDB cancelled the payment.\n- `ERROR`: Issue arose when attempting to complete payment.\n- `FAILED`: MongoDB tried to charge the credit card without success.\n- `FAILED_AUTHENTICATION`: Strong Customer Authentication has failed. Confirm that your payment method is authenticated.\n- `FORGIVEN`: Customer initiated payment which MongoDB later forgave.\n- `INVOICED`: MongoDB issued an invoice that included this line item.\n- `NEW`: Customer provided a method of payment, but MongoDB hasn't tried to charge the credit card.\n- `PAID`: Customer submitted a successful payment.\n- `PARTIAL_PAID`: Customer paid for part of this line item.",
      }),
    subtotalCents: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          'Sum of all positive invoice line items contained in this invoice. This parameter expresses its value in cents (100ths of one US Dollar).',
        readOnly: true,
      }),
    unitPrice: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The unit price applied to `amountBilledCents` to compute total payment amount. This value is represented as a decimal string.',
        readOnly: true,
      }),
    updated: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'Date and time when the customer made an update to this payment attempt. This parameter expresses its value in the ISO 8601 timestamp format in UTC.',
        readOnly: true,
      }),
  })
  .openapi({
    description: 'Funds transferred to MongoDB to cover the specified service in this invoice.',
    title: 'Payment',
    required: [],
  })
  .openapi('BillingPayment')

