const StreamsSchemaRegistryConnectionSchema: z.ZodType<StreamsSchemaRegistryConnectionType> = z
  .lazy(() =>
    StreamsConnectionSchema.and(
      z
        .object({
          provider: z
            .literal('CONFLUENT')
            .exactOptional()
            .openapi({ description: 'The Schema Registry provider.' }),
          schemaRegistryAuthentication: SchemaRegistryAuthenticationSchema.exactOptional(),
          schemaRegistryUrls: z
            .array(z.url().openapi({ description: 'Schema Registry URL.' }))
            .max(10)
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            })
            .exactOptional()
            .openapi({
              description:
                'List of Schema Registry endpoint URLs used by this connection. Each URL must use the http or https scheme and specify a valid host and optional port.',
            }),
        })
        .openapi({ required: [] }),
    ).openapi({
      description: 'The configuration for Schema Registry connections.',
      required: ['provider', 'schemaRegistryAuthentication', 'schemaRegistryUrls'],
    }),
  )
  .openapi('StreamsSchemaRegistryConnection')

