const AdvancedClusterDescriptionSchema = z
  .object({
    acceptDataRisksAndForceReplicaSetReconfig: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'If reconfiguration is necessary to regain a primary due to a regional outage, submit this field alongside your topology reconfiguration to request a new regional outage resistant topology. Forced reconfigurations during an outage of the majority of electable nodes carry a risk of data loss if replicated writes (even majority committed writes) have not been replicated to the new primary node. MongoDB Atlas docs contain more information. To proceed with an operation which carries that risk, set `acceptDataRisksAndForceReplicaSetReconfig` to the current date. This parameter expresses its value in the ISO 8601 timestamp format in UTC.',
        externalDocs: {
          description: 'Reconfiguring a Replica Set during a regional outage',
          url: 'https://dochub.mongodb.org/core/regional-outage-reconfigure-replica-set',
        },
      }),
    advancedConfiguration: ApiAtlasClusterAdvancedConfigurationViewSchema.exactOptional(),
    backupEnabled: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          "Flag that indicates whether the cluster can perform backups. If set to `true`, the cluster can perform backups. You must set this value to `true` for NVMe clusters. Backup uses [Cloud Backups](https://docs.atlas.mongodb.com/backup/cloud-backup/overview/) for dedicated clusters and [Shared Cluster Backups](https://docs.atlas.mongodb.com/backup/shared-tier/overview/) for tenant clusters. If set to `false`, the cluster doesn't use backups.",
      }),
    biConnector: BiConnectorSchema.exactOptional(),
    clusterType: z
      .enum(['REPLICASET', 'SHARDED', 'GEOSHARDED'])
      .exactOptional()
      .openapi({ description: 'Configuration of nodes that comprise the cluster.' }),
    configServerManagementMode: z
      .enum(['ATLAS_MANAGED', 'FIXED_TO_DEDICATED'])
      .default('ATLAS_MANAGED')
      .exactOptional()
      .openapi({
        description:
          "Config Server Management Mode for creating or updating a sharded cluster. When configured as `ATLAS_MANAGED`, Atlas may automatically switch the cluster's config server type for optimal performance and savings. When configured as `FIXED_TO_DEDICATED`, the cluster will always use a dedicated config server.",
        externalDocs: {
          description: 'MongoDB Sharded Cluster Config Servers',
          url: 'https://dochub.mongodb.org/docs/manual/core/sharded-cluster-config-servers',
        },
      }),
    configServerType: z
      .enum(['DEDICATED', 'EMBEDDED'])
      .exactOptional()
      .openapi({
        description: "Describes a sharded cluster's config server type.",
        externalDocs: {
          description: 'MongoDB Sharded Cluster Config Servers',
          url: 'https://dochub.mongodb.org/docs/manual/core/sharded-cluster-config-servers',
        },
        readOnly: true,
      }),
    connectionStrings: ClusterConnectionStringsSchema.exactOptional(),
    createDate: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'Date and time when MongoDB Cloud created this cluster. This parameter expresses its value in ISO 8601 format in UTC.',
        readOnly: true,
      }),
    diskSizeGB: z
      .float64()
      .exactOptional()
      .openapi({
        description:
          'Storage capacity of instance data volumes expressed in gigabytes. Increase this number to add capacity.\n\n This value is not configurable on M0/M2/M5 clusters.\n\n MongoDB Cloud requires this parameter if you set `replicationSpecs`.\n\n If you specify a disk size below the minimum (10 GB), this parameter defaults to the minimum disk size value. \n\n Storage charge calculations depend on whether you choose the default value or a custom value.\n\n The maximum value for disk storage cannot exceed 50 times the maximum RAM for the selected cluster. If you require more storage space, consider upgrading your cluster to a higher tier.',
        externalDocs: {
          description: 'Customize Storage',
          url: 'https://dochub.mongodb.org/core/customize-storage',
        },
      }),
    diskWarmingMode: z
      .enum(['FULLY_WARMED', 'VISIBLE_EARLIER'])
      .default('FULLY_WARMED')
      .exactOptional()
      .openapi({
        description: 'Disk warming mode selection.',
        externalDocs: {
          description: 'Reduce Secondary Disk Warming Impact',
          url: 'https://docs.atlas.mongodb.com/reference/replica-set-tags/#reduce-secondary-disk-warming-impact',
        },
      }),
    encryptionAtRestProvider: z
      .enum(['NONE', 'AWS', 'AZURE', 'GCP'])
      .exactOptional()
      .openapi({
        description:
          'Cloud service provider that manages your customer keys to provide an additional layer of encryption at rest for the cluster. To enable customer key management for encryption at rest, the cluster `replicationSpecs[n].regionConfigs[m].{type}Specs.instanceSize` setting must be `M10` or higher and `"backupEnabled" : false` or omitted entirely.',
        externalDocs: {
          description: 'Encryption at Rest using Customer Key Management',
          url: 'https://www.mongodb.com/docs/atlas/security-kms-encryption/',
        },
      }),
    featureCompatibilityVersion: z
      .string()
      .exactOptional()
      .openapi({ description: 'Feature compatibility version of the cluster.', readOnly: true }),
    featureCompatibilityVersionExpirationDate: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'Feature compatibility version expiration date. This parameter expresses its value in the ISO 8601 timestamp format in UTC.',
        readOnly: true,
      }),
    globalClusterSelfManagedSharding: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Set this field to configure the Sharding Management Mode when creating a new Global Cluster.\n\nWhen set to false, the management mode is set to Atlas-Managed Sharding. This mode fully manages the sharding of your Global Cluster and is built to provide a seamless deployment experience.\n\nWhen set to true, the management mode is set to Self-Managed Sharding. This mode leaves the management of shards in your hands and is built to provide an advanced and flexible deployment experience.\n\nThis setting cannot be changed once the cluster is deployed.',
        externalDocs: {
          description: 'Creating a Global Cluster',
          url: 'https://dochub.mongodb.org/core/global-cluster-management',
        },
      }),
    groupId: z
      .string()
      .regex(/^([a-f0-9]{24})$/)
      .exactOptional()
      .openapi({
        description: 'Unique 24-hexadecimal character string that identifies the project.',
        example: '32b6e34b3d91647abb20e7b8',
        readOnly: true,
      }),
    id: z
      .string()
      .regex(/^([a-f0-9]{24})$/)
      .exactOptional()
      .openapi({
        description: 'Unique 24-hexadecimal digit string that identifies the cluster.',
        example: '32b6e34b3d91647abb20e7b8',
        readOnly: true,
      }),
    labels: z
      .array(ComponentLabelSchema)
      .exactOptional()
      .openapi({
        deprecated: true,
        description:
          "Collection of key-value pairs between 1 to 255 characters in length that tag and categorize the cluster. The MongoDB Cloud console doesn't display your labels.\n\nCluster labels are deprecated and will be removed in a future release. We strongly recommend that you use Resource tags instead.",
        externalDocs: {
          description: 'Resource Tags',
          url: 'https://dochub.mongodb.org/core/add-cluster-tag-atlas',
        },
      }),
    links: z
      .array(LinkSchema)
      .exactOptional()
      .openapi({
        description:
          'List of one or more Uniform Resource Locators (URLs) that point to API sub-resources, related API resources, or both. RFC 5988 outlines these relationships.',
        externalDocs: {
          description: 'Web Linking Specification (RFC 5988)',
          url: 'https://datatracker.ietf.org/doc/html/rfc5988',
        },
        readOnly: true,
      }),
    mongoDBEmployeeAccessGrant: EmployeeAccessGrantViewSchema.exactOptional(),
    mongoDBMajorVersion: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'MongoDB major version of the cluster.\n\nOn creation: Choose from the available versions of MongoDB, or leave unspecified for the current recommended default in the MongoDB Cloud platform. The recommended version is a recent Long Term Support version. The default is not guaranteed to be the most recently released version throughout the entire release cycle. For versions available in a specific project, see the linked documentation or use the API endpoint for [project LTS versions endpoint](#tag/Projects/operation/getProjectLTSVersions).\n\n On update: Increase version only by 1 major version at a time. If the cluster is pinned to a MongoDB feature compatibility version exactly one major version below the current MongoDB version, the MongoDB version can be downgraded to the previous major version.',
        externalDocs: {
          description: 'Available MongoDB Versions in Atlas',
          url: 'https://www.mongodb.com/docs/atlas/reference/faq/database/#which-versions-of-mongodb-do-service-clusters-use-',
        },
      }),
    mongoDBVersion: z
      .string()
      .regex(/([\d]+\.[\d]+\.[\d]+)/)
      .exactOptional()
      .openapi({ description: 'Version of MongoDB that the cluster runs.', readOnly: true }),
    name: z
      .string()
      .regex(/^[a-zA-Z0-9][a-zA-Z0-9-]*$/)
      .exactOptional()
      .openapi({ description: 'Human-readable label that identifies the advanced cluster.' }),
    paused: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Flag that indicates whether the cluster is paused.' }),
    pitEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'Flag that indicates whether the cluster uses continuous cloud backups.',
        externalDocs: {
          description: 'Continuous Cloud Backups',
          url: 'https://docs.atlas.mongodb.com/backup/cloud-backup/overview/',
        },
      }),
    replicaSetScalingStrategy: z
      .enum(['SEQUENTIAL', 'WORKLOAD_TYPE', 'NODE_TYPE'])
      .default('WORKLOAD_TYPE')
      .exactOptional()
      .openapi({
        description:
          'Set this field to configure the replica set scaling mode for your cluster.\n\nBy default, Atlas scales under `WORKLOAD_TYPE`. This mode allows Atlas to scale your analytics nodes in parallel to your operational nodes.\n\nWhen configured as `SEQUENTIAL`, Atlas scales all nodes sequentially. This mode is intended for steady-state workloads and applications performing latency-sensitive secondary reads.\n\nWhen configured as `NODE_TYPE`, Atlas scales your electable nodes in parallel with your read-only and analytics nodes. This mode is intended for large, dynamic workloads requiring frequent and timely cluster tier scaling. This is the fastest scaling strategy, but it might impact latency of workloads when performing extensive secondary reads.',
        externalDocs: {
          description: 'Modify the Replica Set Scaling Mode',
          url: 'https://dochub.mongodb.org/core/scale-nodes',
        },
      }),
    replicationSpecs: z
      .array(ReplicationSpecSchema)
      .exactOptional()
      .openapi({
        description:
          'List of settings that configure your cluster regions. For Global Clusters, each object in the array represents a zone where your clusters nodes deploy. For non-Global sharded clusters and replica sets, this array has one object representing where your clusters nodes deploy.',
      }),
    rootCertType: z
      .literal('ISRGROOTX1')
      .default('ISRGROOTX1')
      .exactOptional()
      .openapi({
        description:
          'Root Certificate Authority that MongoDB Atlas cluster uses. MongoDB Cloud supports Internet Security Research Group.',
      }),
    stateName: z
      .enum(['IDLE', 'CREATING', 'UPDATING', 'DELETING', 'REPAIRING'])
      .exactOptional()
      .openapi({
        description:
          'Human-readable label that indicates any current activity being taken on this cluster by the Atlas control plane. With the exception of CREATING and DELETING states, clusters should always be available and have a Primary node even when in states indicating ongoing activity.\n\n - `IDLE`: Atlas is making no changes to this cluster and all changes requested via the UI or API can be assumed to have been applied.\n - `CREATING`: A cluster being provisioned for the very first time returns state CREATING until it is ready for connections. Ensure IP Access List and DB Users are configured before attempting to connect.\n - `UPDATING`: A change requested via the UI, API, AutoScaling, or other scheduled activity is taking place.\n - `DELETING`: The cluster is in the process of deletion and will soon be deleted.\n - `REPAIRING`: One or more nodes in the cluster are being returned to service by the Atlas control plane. Other nodes should continue to provide service as normal.',
        readOnly: true,
      }),
    tags: z
      .array(ResourceTagSchema)
      .exactOptional()
      .openapi({
        description:
          'List that contains key-value pairs between 1 to 255 characters in length for tagging and categorizing the cluster.',
        externalDocs: {
          description: 'Resource Tags',
          url: 'https://dochub.mongodb.org/core/add-cluster-tag-atlas',
        },
      }),
    terminationProtectionEnabled: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          "Flag that indicates whether termination protection is enabled on the cluster. If set to `true`, MongoDB Cloud won't delete the cluster. If set to `false`, MongoDB Cloud will delete the cluster.",
      }),
    versionReleaseSystem: z
      .enum(['LTS', 'CONTINUOUS'])
      .default('LTS')
      .exactOptional()
      .openapi({
        description:
          'Method by which the cluster maintains the MongoDB versions. If value is `CONTINUOUS`, you must not specify `mongoDBMajorVersion`.',
      }),
  })
  .openapi({ required: [] })
  .openapi('AdvancedClusterDescription')

const DiskBackupApiPolicyItemSchema = z
  .object({
    frequencyInterval: z
      .union([
        z.literal(1),
        z.literal(2),
        z.literal(3),
        z.literal(4),
        z.literal(5),
        z.literal(6),
        z.literal(7),
        z.literal(8),
        z.literal(9),
        z.literal(10),
        z.literal(11),
        z.literal(12),
        z.literal(13),
        z.literal(14),
        z.literal(15),
        z.literal(16),
        z.literal(17),
        z.literal(18),
        z.literal(19),
        z.literal(20),
        z.literal(21),
        z.literal(22),
        z.literal(23),
        z.literal(24),
        z.literal(25),
        z.literal(26),
        z.literal(27),
        z.literal(28),
        z.literal(40),
      ])
      .openapi({
        description:
          'Number that indicates the frequency interval for a set of Snapshots. A value of `1` specifies the first instance of the corresponding `frequencyType`.\n\n- In a yearly policy item, `1` indicates that the yearly Snapshot occurs on the first day of January and `12` indicates the first day of December.\n\n- In a monthly policy item, `1` indicates that the monthly Snapshot occurs on the first day of the month and `40` indicates the last day of the month.\n\n- In a weekly policy item, `1` indicates that the weekly Snapshot occurs on Monday and `7` indicates Sunday.\n\n- In an hourly policy item, you can set the frequency interval to `1`, `2`, `4`, `6`, `8`, or `12`. For hourly policy items for NVMe clusters, MongoDB Cloud accepts only `12` as the frequency interval value.\n\n MongoDB Cloud ignores this setting for non-hourly policy items in Backup Compliance Policy settings.',
      }),
    frequencyType: z
      .enum(['daily', 'hourly', 'weekly', 'monthly', 'yearly', 'ondemand'])
      .openapi({
        description:
          'Human-readable label that identifies the frequency type associated with the backup policy.',
      }),
    id: z
      .string()
      .regex(/^([a-f0-9]{24})$/)
      .exactOptional()
      .openapi({
        description: 'Unique 24-hexadecimal digit string that identifies this backup policy item.',
        example: '32b6e34b3d91647abb20e7b8',
        readOnly: true,
      }),
    retentionUnit: z
      .enum(['days', 'weeks', 'months', 'years'])
      .openapi({ description: 'Unit of time in which MongoDB Cloud measures Snapshot retention.' }),
    retentionValue: z
      .int32()
      .openapi({
        description:
          'Duration in days, weeks, months, or years that MongoDB Cloud retains the Snapshot. For less frequent policy items, MongoDB Cloud requires that you specify a value greater than or equal to the value specified for more frequent policy items.\n\nFor example: If the hourly policy item specifies a retention of two days, you must specify two days or greater for the retention of the weekly policy item.',
      }),
  })
  .openapi({
    description: 'Specifications for one policy.',
    required: ['frequencyInterval', 'frequencyType', 'retentionUnit', 'retentionValue'],
  })
  .openapi('DiskBackupApiPolicyItem')

const AdvancedDiskBackupSnapshotSchedulePolicySchema = z
  .object({
    id: z
      .string()
      .regex(/^([a-f0-9]{24})$/)
      .exactOptional()
      .openapi({
        description: 'Unique 24-hexadecimal digit string that identifies this backup policy.',
        example: '32b6e34b3d91647abb20e7b8',
      }),
    policyItems: z
      .array(DiskBackupApiPolicyItemSchema)
      .openapi({ description: 'List that contains the specifications for one policy.' }),
  })
