const AuthFederationRoleMappingSchema = z
  .object({
    externalGroupName: z
      .string()
      .min(1)
      .max(200)
      .openapi({
        description:
          'Unique human-readable label that identifies the identity provider group to which this role mapping applies.',
      }),
    id: z
      .string()
      .regex(/^([a-f0-9]{24})$/)
      .exactOptional()
      .openapi({
        description: 'Unique 24-hexadecimal digit string that identifies this role mapping.',
        example: '32b6e34b3d91647abb20e7b8',
        readOnly: true,
      }),
    roleAssignments: z
      .array(ConnectedOrgConfigRoleAssignmentSchema)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({
        description:
          'Atlas roles and the unique identifiers of the groups and organizations associated with each role. The array must include at least one element with an Organization role and its respective `orgId`. Each element in the array can have a value for `orgId` or `groupId`, but not both.',
      }),
  })
  .openapi({
    description: 'Mapping settings that link one IdP and MongoDB Cloud.',
    required: ['externalGroupName', 'roleAssignments'],
    title: 'Federated Authentication Role Mapping',
  })
  .openapi('AuthFederationRoleMapping')

