const CloudAppUserSchema = z
  .object({
    country: z
      .string()
      .regex(/^([A-Z]{2})$/)
      .openapi({
        description:
          "Two alphabet characters that identifies MongoDB Cloud user's geographic location. This parameter uses the ISO 3166-1a2 code format.",
      }),
    createdAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'Date and time when the current account is created. This value is in the ISO 8601 timestamp format in UTC.',
        readOnly: true,
      }),
    emailAddress: z
      .email()
      .openapi({
        deprecated: true,
        description: 'Email address that belongs to the MongoDB Cloud user.',
        readOnly: true,
      }),
    firstName: z
      .string()
      .openapi({ description: 'First or given name that belongs to the MongoDB Cloud user.' }),
    id: z
      .string()
      .regex(/^([a-f0-9]{24})$/)
      .exactOptional()
      .openapi({
        description: 'Unique 24-hexadecimal digit string that identifies the MongoDB Cloud user.',
        example: '32b6e34b3d91647abb20e7b8',
        readOnly: true,
      }),
    lastAuth: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'Date and time when the current account last authenticated. This value is in the ISO 8601 timestamp format in UTC.',
        readOnly: true,
      }),
    lastName: z
      .string()
      .openapi({
        description: 'Last name, family name, or surname that belongs to the MongoDB Cloud user.',
      }),
    links: z
      .array(LinkSchema)
      .exactOptional()
      .openapi({
        description:
          'List of one or more Uniform Resource Locators (URLs) that point to API sub-resources, related API resources, or both. RFC 5988 outlines these relationships.',
        externalDocs: {
          description: 'Web Linking Specification (RFC 5988)',
          url: 'https://datatracker.ietf.org/doc/html/rfc5988',
        },
        readOnly: true,
      }),
    mobileNumber: z
      .string()
      .regex(
        /(?:(?:\\+?1\\s*(?:[.-]\\s*)?)?(?:(\\s*([2-9]1[02-9]|[2-9][02-8]1|[2-9][02-8][02-9])\\s*)|([2-9]1[02-9]|[2-9][02-8]1|[2-9][02-8][02-9]))\\s*(?:[.-]\\s*)?)([2-9]1[02-9]|[2-9][02-9]1|[2-9][02-9]{2})\\s*(?:[.-]\\s*)?([0-9]{4})$/,
      )
      .openapi({ description: 'Mobile phone number that belongs to the MongoDB Cloud user.' }),
    password: z
      .string()
      .min(8)
      .openapi({
        description:
          'Password applied with the username to log in to MongoDB Cloud. MongoDB Cloud does not return this parameter except in response to creating a new MongoDB Cloud user. Only the MongoDB Cloud user can update their password after it has been set from the MongoDB Cloud console.',
      }),
    roles: z
      .array(CloudAccessRoleAssignmentSchema)
      .openapi({
        description:
          "List of objects that display the MongoDB Cloud user's roles and the corresponding organization or project to which that role applies. A role can apply to one organization or one project but not both.",
      }),
    teamIds: z
      .array(
        z
          .string()
          .regex(/^([a-f0-9]{24})$/)
          .openapi({
            description:
              'Unique 24-hexadecimal digit string that identifies the team to which this MongoDB Cloud user belongs.',
            example: '32b6e34b3d91647abb20e7b8',
          }),
      )
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({
        description:
          'List of unique 24-hexadecimal digit strings that identifies the teams to which this MongoDB Cloud user belongs.',
        readOnly: true,
      }),
    username: z
      .email()
      .openapi({
        description: 'Email address that represents the username of the MongoDB Cloud user.',
      }),
  })
  .openapi({
    required: [
      'country',
      'emailAddress',
      'firstName',
      'lastName',
      'mobileNumber',
      'password',
      'roles',
      'username',
    ],
  })
