const FederationSamlIdentityProviderSchema = z
  .object({
    acsUrl: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'URL that points to where to send the SAML response.' }),
    associatedDomains: z
      .array(z.string())
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({
        description: 'List that contains the domains associated with the identity provider.',
      }),
    associatedOrgs: z
      .array(ConnectedOrgConfigSchema)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({
        description:
          'List that contains the connected organization configurations associated with the identity provider.',
      }),
    audienceUri: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Unique string that identifies the intended audience of the SAML assertion.',
      }),
    createdAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'Date that the identity provider was created on. This parameter expresses its value in the ISO 8601 timestamp format in UTC.',
        readOnly: true,
      }),
    description: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'The description of the identity provider.' }),
    displayName: z
      .string()
      .exactOptional()
      .openapi({ description: 'Human-readable label that identifies the identity provider.' }),
    id: z
      .string()
      .regex(/^([a-f0-9]{24})$/)
      .openapi({
        description: 'Unique 24-hexadecimal digit string that identifies the identity provider.',
        example: '32b6e34b3d91647abb20e7b8',
        readOnly: true,
      }),
    idpType: z
      .enum(['WORKFORCE', 'WORKLOAD'])
      .exactOptional()
      .openapi({
        description:
          'String enum that indicates the type of the identity provider. Default is WORKFORCE.',
      }),
    issuerUri: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Unique string that identifies the issuer of the SAML Assertion or OIDC metadata/discovery document URL.',
      }),
    oktaIdpId: z
      .string()
      .regex(/^([a-f0-9]{20})$/)
      .nullable()
      .openapi({
        description: 'Legacy 20-hexadecimal digit string that identifies the identity provider.',
      }),
    pemFileInfo: PemFileInfoSchema.exactOptional(),
    protocol: z
      .enum(['SAML', 'OIDC'])
      .exactOptional()
      .openapi({
        description:
          'String enum that indicates the protocol of the identity provider. Either SAML or OIDC.',
      }),
    requestBinding: z
      .enum(['HTTP-POST', 'HTTP-REDIRECT'])
      .exactOptional()
      .openapi({
        description:
          'SAML Authentication Request Protocol HTTP method binding (POST or REDIRECT) that Federated Authentication uses to send the authentication request.',
      }),
    responseSignatureAlgorithm: z
      .enum(['SHA-1', 'SHA-256'])
      .exactOptional()
      .openapi({
        description:
          'Signature algorithm that Federated Authentication uses to encrypt the identity provider signature.',
      }),
    slug: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Custom SSO URL for the identity provider.' }),
    ssoDebugEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'Flag that indicates whether the identity provider has SSO debug enabled.',
      }),
    ssoUrl: z
      .string()
      .exactOptional()
      .openapi({
        description: 'URL that points to the receiver of the SAML authentication request.',
      }),
    status: z
      .enum(['ACTIVE', 'INACTIVE'])
      .exactOptional()
      .openapi({
        description: 'String enum that indicates whether the identity provider is active.',
      }),
    updatedAt: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Date that the identity provider was last updated on. This parameter expresses its value in the ISO 8601 timestamp format in UTC.',
        readOnly: true,
      }),
  })
  .openapi({ required: ['id', 'oktaIdpId'], title: 'SAML' })
  .openapi('FederationSamlIdentityProvider')

