const ManagedNamespacesSchema = z
  .object({
    collection: z
      .string()
      .openapi({
        description: 'Human-readable label of the collection to manage for this Global Cluster.',
      }),
    customShardKey: z
      .string()
      .openapi({
        description:
          'Database parameter used to divide the *collection* into shards. Global clusters require a compound shard key. This compound shard key combines the location parameter and the user-selected custom key.',
      }),
    db: z
      .string()
      .openapi({
        description: 'Human-readable label of the database to manage for this Global Cluster.',
      }),
    isCustomShardKeyHashed: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Flag that indicates whether someone hashed the custom shard key for the specified collection. If you set this value to `false`, MongoDB Cloud uses ranged sharding.',
        externalDocs: {
          description: 'Hashed Shard Keys',
          url: 'https://www.mongodb.com/docs/manual/reference/method/sh.shardCollection/#hashed-shard-keys',
        },
      }),
    isShardKeyUnique: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Flag that indicates whether someone [hashed](https://www.mongodb.com/docs/manual/reference/method/sh.shardCollection/#hashed-shard-keys) the custom shard key. If this parameter returns `false`, this cluster uses [ranged sharding](https://www.mongodb.com/docs/manual/core/ranged-sharding/).',
      }),
    numInitialChunks: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64().max(8192n),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        maximum: 8192,
        description:
          'Minimum number of chunks to create initially when sharding an empty collection with a [hashed shard key](https://www.mongodb.com/docs/manual/core/hashed-sharding/).',
        externalDocs: {
          description: 'Global Cluster Sharding',
          url: 'https://www.mongodb.com/docs/atlas/shard-global-collection/',
        },
      }),
    presplitHashedZones: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Flag that indicates whether MongoDB Cloud should create and distribute initial chunks for an empty or non-existing collection. MongoDB Cloud distributes data based on the defined zones and zone ranges for the collection.',
        externalDocs: {
          description: 'Hashed Shard Key',
          url: 'https://www.mongodb.com/docs/manual/core/hashed-sharding/',
        },
      }),
  })
  .openapi({ required: ['collection', 'customShardKey', 'db'] })
  .openapi('ManagedNamespaces')

