const MatcherHostTypeSchema = z
  .enum(['STANDALONE', 'PRIMARY', 'SECONDARY', 'ARBITER', 'MONGOS', 'CONFIG', 'MONGOT'])
  .openapi({
    description: 'Value to match or exceed using the specified `matchers.operator`.',
    example: 'STANDALONE',
    title: 'Matcher Host Types',
  })
  .openapi('MatcherHostType')

const HostMatcherSchema = z
  .object({
    fieldName: HostMatcherFieldSchema,
    operator: z
      .enum([
        'EQUALS',
        'CONTAINS',
        'STARTS_WITH',
        'ENDS_WITH',
        'NOT_EQUALS',
        'NOT_CONTAINS',
        'REGEX',
      ])
      .openapi({
        description:
          'Comparison operator to apply when checking the current metric value against **matcher[n].value**. The `REGEX` operator only supports inclusive matches. Use the `NOT_CONTAINS` operator to exclude values.',
      }),
    value: MatcherHostTypeSchema.exactOptional(),
  })
  .openapi({
    description: 'Rules to apply when comparing an host against this alert configuration.',
    required: ['fieldName', 'operator'],
    title: 'Matchers',
  })
  .openapi('HostMatcher')

