const HostMetricAlertConfigViewForNdsGroupSchema = z
  .object({
    created: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'Date and time when MongoDB Cloud created the alert configuration. This parameter expresses its value in the ISO 8601 timestamp format in UTC.',
        externalDocs: { description: 'ISO 8601', url: 'https://en.wikipedia.org/wiki/ISO_8601' },
        readOnly: true,
      }),
    enabled: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Flag that indicates whether someone enabled this alert configuration for the specified project.',
      }),
    eventTypeName: HostMetricEventTypeViewAlertableSchema,
    groupId: z
      .string()
      .regex(/^([a-f0-9]{24})$/)
      .exactOptional()
      .openapi({
        description:
          'Unique 24-hexadecimal digit string that identifies the project that owns this alert configuration.',
        example: '32b6e34b3d91647abb20e7b8',
        readOnly: true,
      }),
    id: z
      .string()
      .regex(/^([a-f0-9]{24})$/)
      .exactOptional()
      .openapi({
        description: 'Unique 24-hexadecimal digit string that identifies this alert configuration.',
        example: '32b6e34b3d91647abb20e7b8',
        readOnly: true,
      }),
    links: z
      .array(LinkSchema)
      .exactOptional()
      .openapi({
        description:
          'List of one or more Uniform Resource Locators (URLs) that point to API sub-resources, related API resources, or both. RFC 5988 outlines these relationships.',
        externalDocs: {
          description: 'Web Linking Specification (RFC 5988)',
          url: 'https://datatracker.ietf.org/doc/html/rfc5988',
        },
        readOnly: true,
      }),
    matchers: z
      .array(HostMatcherSchema)
      .exactOptional()
      .openapi({
        description:
          'List of rules that determine whether MongoDB Cloud checks an object for the alert configuration. You can filter using the matchers array if the `eventTypeName` specifies an event for a host, replica set, or sharded cluster.',
      }),
    metricThreshold: HostMetricThresholdSchema.exactOptional(),
    notifications: z
      .array(AlertsNotificationRootForGroupSchema)
      .min(1)
      .max(25)
      .openapi({
        description: 'List that contains the targets that MongoDB Cloud sends notifications.',
      }),
    severityOverride: EventSeveritySchema.exactOptional(),
    updated: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'Date and time when someone last updated this alert configuration. This parameter expresses its value in the ISO 8601 timestamp format in UTC.',
        externalDocs: { description: 'ISO 8601', url: 'https://en.wikipedia.org/wiki/ISO_8601' },
        readOnly: true,
      }),
  })
  .openapi({
    description:
      'Host metric alert configuration allows to select which mongod host metrics trigger alerts and how users are notified.',
    required: ['eventTypeName', 'notifications'],
    title: 'Host Metric Alert Configuration',
  })
  .openapi('HostMetricAlertConfigViewForNdsGroup')

