const OAuthConfigResponseSchema = z
  .object({
    clientAuthMethod: z
      .enum(['CLIENT_SECRET', 'PRIVATE_KEY_JWT'])
      .openapi({ description: 'How the client authenticates to the token endpoint.' }),
    clientId: z
      .string()
      .max(2048)
      .openapi({ description: 'OAuth 2.0 client identifier registered with the token endpoint.' }),
    scopes: z
      .array(z.string().max(256))
      .max(20)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({ description: 'OAuth 2.0 scopes requested on the token.' }),
    signingKeyInfo: OAuthSigningKeyInfoSchema.exactOptional(),
    tokenEndpoint: z.string().max(2048).openapi({ description: 'OAuth 2.0 token endpoint URL.' }),
    tokenRequestParams: z
      .record(
        z.string(),
        z
          .string()
          .openapi({ description: 'Provider-specific parameters added to the token request.' }),
      )
      .refine((val) => Object.keys(val).length <= 10)
      .exactOptional()
      .openapi({ description: 'Provider-specific parameters added to the token request.' }),
  })
  .openapi({
    description:
      'OAuth 2.0 configuration returned for a metric integration. Secrets are never returned.',
    required: ['clientAuthMethod', 'clientId', 'tokenEndpoint'],
    title: 'OAuth Config Response',
  })
  .openapi('OAuthConfigResponse')

