const OperationErrorSchema = z
  .object({
    code: z.string().openapi({ description: 'Machine-readable error code.' }),
    details: z
      .record(z.string(), z.object({}).openapi({ description: 'Additional error details.' }))
      .nullable()
      .exactOptional()
      .openapi({ description: 'Additional error details.' }),
    message: z.string().openapi({ description: 'Human-readable error message.' }),
    retryStrategy: z
      .enum(['IMMEDIATE', 'BACKOFF', 'NONE'])
      .nullable()
      .exactOptional()
      .openapi({ description: 'Recommended strategy for retrying the operation.' }),
    retryable: z
      .boolean()
      .openapi({ description: 'Flag that indicates whether the operation can be retried.' }),
  })
  .openapi({
    description: 'Details about a failed operation.',
    readOnly: true,
    required: ['code', 'message', 'retryable'],
  })
  .openapi('OperationError')

const OperationProgressSchema = z
  .object({
    completed: z.int32().exactOptional().openapi({ description: 'Number of completed units.' }),
    total: z.int32().exactOptional().openapi({ description: 'Total number of units.' }),
    unit: z
      .string()
      .exactOptional()
      .openapi({ description: 'Unit measured by completed and total.' }),
  })
  .openapi({ description: 'Progress made by an active operation.', readOnly: true, required: [] })
  .openapi('OperationProgress')

const OperationResponseSchema = z
  .object({
    createdAt: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'Creation time in ISO 8601 timestamp format in UTC.',
        readOnly: true,
      }),
    customMethod: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Name of a custom operation. Required for CUSTOM operations.',
        readOnly: true,
      }),
    error: OperationErrorSchema.exactOptional(),
    estimatedCompletionTime: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Estimated completion time in ISO 8601 timestamp format in UTC.',
        readOnly: true,
      }),
    expiresAt: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'Expiration time in ISO 8601 timestamp format in UTC.',
        readOnly: true,
      }),
    operationId: z
      .string()
      .openapi({ description: 'Unique identifier of the operation.', readOnly: true }),
    operationType: z
      .enum(['CREATE', 'UPDATE', 'DELETE', 'CUSTOM'])
      .openapi({ description: 'Type of mutation performed by the operation.', readOnly: true }),
    progress: OperationProgressSchema.exactOptional(),
    resultHref: z
      .url()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'URI of the affected resource. Required when status is SUCCEEDED.',
        readOnly: true,
      }),
    retryAfterSeconds: z
      .int32()
      .min(1)
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Recommended polling delay. Required while the operation is active.',
        readOnly: true,
      }),
    status: z
      .enum(['PENDING', 'IN_PROGRESS', 'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED'])
      .openapi({ description: 'State of the operation.', readOnly: true }),
    statusMessage: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Human-readable operation status.', readOnly: true }),
    updatedAt: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'Last update time in ISO 8601 timestamp format in UTC.',
        readOnly: true,
      }),
  })
  .openapi({
    description: 'Status of a long-running operation.',
    required: ['createdAt', 'expiresAt', 'operationId', 'operationType', 'status', 'updatedAt'],
  })
  .openapi('OperationResponse')

