const OrgDelegationSettingsResponseSchema = z
  .object({
    delegatedMcpAccess: z
      .enum(['DISALLOWED', 'READ_ONLY', 'READ_WRITE'])
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Policy that controls how MCP (Model Context Protocol) delegated access is permitted within this organization. Possible values are `DISALLOWED`, `READ_ONLY`, and `READ_WRITE`. Defaults to `DISALLOWED`.',
      }),
    delegatedPartnerAccess: z
      .enum(['DISALLOWED', 'READ_WRITE'])
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Policy that controls whether partner delegated access is permitted within this organization. Possible values are `DISALLOWED` and `READ_WRITE`. Defaults to `DISALLOWED`.',
      }),
    idleRefreshTokenLifetime: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64().min(1n).max(31536000n),
      )
      .nullable()
      .exactOptional()
      .openapi({
        type: ['integer', 'null'],
        format: 'int64',
        minimum: 1,
        maximum: 31536000,
        description:
          'Maximum number of seconds a refresh token may be idle before it expires. When not set, the system default applies.',
      }),
    maximumRefreshTokenLifetime: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64().min(1n).max(31536000n),
      )
      .nullable()
      .exactOptional()
      .openapi({
        type: ['integer', 'null'],
        format: 'int64',
        minimum: 1,
        maximum: 31536000,
        description:
          'Maximum lifetime of a refresh token in seconds, regardless of activity. When not set, the system default applies.',
      }),
  })
  .openapi({ required: [] })
  .openapi('OrgDelegationSettingsResponse')

