const TeamSchema = z
  .object({
    id: z
      .string()
      .regex(/^([a-f0-9]{24})$/)
      .exactOptional()
      .openapi({
        description: 'Unique 24-hexadecimal digit string that identifies this team.',
        example: '32b6e34b3d91647abb20e7b8',
        readOnly: true,
      }),
    links: z
      .array(LinkSchema)
      .exactOptional()
      .openapi({
        description:
          'List of one or more Uniform Resource Locators (URLs) that point to API sub-resources, related API resources, or both. RFC 5988 outlines these relationships.',
        externalDocs: {
          description: 'Web Linking Specification (RFC 5988)',
          url: 'https://datatracker.ietf.org/doc/html/rfc5988',
        },
        readOnly: true,
      }),
    name: z.string().openapi({ description: 'Human-readable label that identifies the team.' }),
    usernames: z
      .array(z.email())
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({ description: 'List that contains the MongoDB Cloud users in this team.' }),
  })
  .openapi({ required: ['name', 'usernames'] })
  .openapi('Team')

