export const getApiAtlasV2GroupsGroupIdClustersClusterNameOnlineArchivesQueryLogsGzRoute =
  createRoute({
    method: 'get',
    path: '/api/atlas/v2/groups/{groupId}/clusters/{clusterName}/onlineArchives/queryLogs.gz',
    tags: ['Online Archive'],
    summary: 'Download Online Archive Query Logs',
    description:
      'Downloads query logs for the specified online archive. The API does not support direct calls with the json response schema. You must request a gzip response schema using an accept header of the format: `Accept: application/vnd.atlas.YYYY-MM-DD+gzip`.',
    externalDocs: {
      description: 'Online Archive',
      url: 'https://docs.atlas.mongodb.com/online-archive/manage-online-archive/#std-label-manage-online-archive',
    },
    operationId: 'downloadGroupClusterOnlineArchiveQueryLogs',
    request: {
      params: z.object({
        groupId: GroupIdParamsSchema,
        clusterName: z
          .string()
          .regex(/^[a-zA-Z0-9][a-zA-Z0-9-]*$/)
          .openapi({
            param: {
              description:
                'Human-readable label that identifies the cluster that contains the collection for which you want to return the query logs from one online archive.',
              in: 'path',
              name: 'clusterName',
              required: true,
              schema: { pattern: '^[a-zA-Z0-9][a-zA-Z0-9-]*$', type: 'string' },
            },
          }),
      }),
      query: z.object({
        envelope: EnvelopeParamsSchema,
        startDate: z
          .preprocess((val) => {
            if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
              return val
            if (/^-?\d+$/.test(val)) return BigInt(val)
            const num = Number(val)
            return Number.isSafeInteger(num) ? BigInt(num) : val
          }, z.int64().min(1199145600n))
          .exactOptional()
          .openapi({
            param: {
              description:
                'Date and time that specifies the starting point for the range of log messages to return. This resource expresses this value in the number of seconds that have elapsed since the [UNIX epoch](https://en.wikipedia.org/wiki/Unix_time).',
              in: 'query',
              name: 'startDate',
              schema: {
                example: 1636481348,
                format: 'int64',
                minimum: 1199145600,
                type: 'integer',
              },
              required: false,
            },
            example: 1636481348,
          }),
        endDate: z
          .preprocess((val) => {
            if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
              return val
            if (/^-?\d+$/.test(val)) return BigInt(val)
            const num = Number(val)
            return Number.isSafeInteger(num) ? BigInt(num) : val
          }, z.int64().min(1199145600n))
          .exactOptional()
          .openapi({
            param: {
              description:
                'Date and time that specifies the end point for the range of log messages to return. This resource expresses this value in the number of seconds that have elapsed since the [UNIX epoch](https://en.wikipedia.org/wiki/Unix_time).',
              in: 'query',
              name: 'endDate',
              schema: {
                example: 1636481348,
                format: 'int64',
                minimum: 1199145600,
                type: 'integer',
              },
              required: false,
            },
            example: 1636481348,
          }),
        archiveOnly: z
          .stringbool()
          .default(false)
          .exactOptional()
          .openapi({
            param: {
              description:
                'Flag that indicates whether to download logs for queries against your online archive only or both your online archive and cluster.',
              in: 'query',
              name: 'archiveOnly',
              schema: { default: false, type: 'boolean' },
              required: false,
            },
          }),
      }),
    },
    responses: {
      200: {
        description: 'OK',
        content: {
          'application/vnd.atlas.2023-01-01+gzip': {
            schema: z
              .file()
              .openapi({
                type: 'string',
                format: 'binary',
                description:
                  'This resource downloads a compressed log file to your current working directory. You can specify its name using the `--output` option or use the default filename using the `-OJ` option. The default filename varies based on whether you download logs for queries of your online archive only or both your online archive and cluster.',
              }),
          },
        },
        headers: z.object({
          'RateLimit-Limit': HeaderRateLimitLimitHeaderSchema,
          'RateLimit-Remaining': HeaderRateLimitRemainingHeaderSchema,
        }),
      },
      400: BadRequestResponse,
      401: UnauthorizedResponse,
      403: ForbiddenResponse,
      404: NotFoundResponse,
      429: TooManyRequestsResponse,
      500: InternalServerErrorResponse,
    },
  })

