export const getApiAtlasV2GroupsGroupIdClustersClusterNameShardMetricsReplicaSetNameMeasurementsRoute =
  createRoute({
    method: 'get',
    path: '/api/atlas/v2/groups/{groupId}/clusters/{clusterName}/shardMetrics/{replicaSetName}/measurements',
    tags: ['Sharding Insights'],
    summary: 'Return Measurements for One Shard',
    description:
      "Returns time series of the requested measurements for one shard of the specified sharded cluster. The series average the readings of the shard's member processes selected by `nodeType`. Responds with a 404 only when no shard with the given `replicaSetName` exists in the cluster; a shard that exists but has no readings yet returns series of `null` data points. Each series carries one data point per `granularity` interval, starting at `start` and not passing `end`. A data point's `value` is `null` when MongoDB Cloud has no reading for that interval; this includes the first minutes after a cluster or shard is created, before its metrics are collected, so `null` must not be read as zero load. Set `period`, or set both `start` and `end`; when neither is set, the response covers the last hour. A request whose window and `granularity` would produce more than 1000 data points per series is rejected.",
    operationId: 'getGroupClusterShardMetricMeasurements',
    request: {
      params: z.object({
        groupId: GroupIdParamsSchema,
        clusterName: z
          .string()
          .regex(/^[a-zA-Z0-9][a-zA-Z0-9-]*$/)
          .openapi({
            param: {
              description: 'Human-readable label that identifies the cluster.',
              in: 'path',
              name: 'clusterName',
              required: true,
              schema: { pattern: '^[a-zA-Z0-9][a-zA-Z0-9-]*$', type: 'string' },
            },
          }),
        replicaSetName: z
          .string()
          .regex(/^[A-Za-z0-9][A-Za-z0-9_-]*$/)
          .openapi({
            param: {
              description:
                'Human-readable label that identifies the shard, as the replica set name of its members.',
              in: 'path',
              name: 'replicaSetName',
              required: true,
              schema: {
                example: 'atlas-12vorz-shard-0',
                pattern: '^[A-Za-z0-9][A-Za-z0-9_-]*$',
                type: 'string',
              },
            },
            example: 'atlas-12vorz-shard-0',
          }),
      }),
      query: z.object({
        envelope: EnvelopeParamsSchema,
        pretty: PrettyParamsSchema,
        m: z
          .preprocess(
            (val) => (val === undefined || Array.isArray(val) ? val : [val]),
            z
              .array(
                z
                  .enum([
                    'SYSTEM_CPU',
                    'SYSTEM_MEMORY',
                    'SYSTEM_NETWORK',
                    'DISK_IOPS',
                    'DISK_LATENCY',
                    'DISK_THROUGHPUT',
                    'DISK_SPACE',
                    'CONNECTIONS',
                    'OPCOUNTERS',
                    'QUEUES',
                    'REPLICATION_LAG',
                  ])
                  .openapi({ description: 'One measurement to return.' }),
              )
              .min(1)
              .max(20)
              .superRefine((items, ctx) => {
                const seen = new Map()
                for (const [i, val] of items.entries()) {
                  const key = JSON.stringify(val)
                  if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                  else seen.set(key, i)
                }
              }),
          )
          .exactOptional()
          .openapi({
            param: {
              description:
                'One or more measurements to return. If omitted, the resource returns all measurements. To specify multiple values for `m`, repeat the `m` parameter for each value.',
              in: 'query',
              name: 'm',
              schema: {
                items: {
                  description: 'One measurement to return.',
                  enum: [
                    'SYSTEM_CPU',
                    'SYSTEM_MEMORY',
                    'SYSTEM_NETWORK',
                    'DISK_IOPS',
                    'DISK_LATENCY',
                    'DISK_THROUGHPUT',
                    'DISK_SPACE',
                    'CONNECTIONS',
                    'OPCOUNTERS',
                    'QUEUES',
                    'REPLICATION_LAG',
                  ],
                  type: 'string',
                },
                maxItems: 20,
                minItems: 1,
                type: 'array',
                uniqueItems: true,
              },
              style: 'form',
              required: false,
            },
          }),
        granularity: z
          .enum(['PT30S', 'PT1M', 'PT3M', 'PT15M', 'PT1H', 'PT3H'])
          .exactOptional()
          .openapi({
            param: {
              description:
                'Interval between consecutive data points, in ISO 8601 duration format. If omitted, MongoDB Cloud chooses the resolution from the width of the window.',
              in: 'query',
              name: 'granularity',
              schema: {
                enum: ['PT30S', 'PT1M', 'PT3M', 'PT15M', 'PT1H', 'PT3H'],
                example: 'PT1M',
                type: 'string',
              },
              required: false,
            },
            example: 'PT1M',
          }),
        period: PeriodParamsSchema,
        start: StartParamsSchema,
        end: EndParamsSchema,
        nodeType: z
          .enum(['ALL', 'PRIMARIES', 'SECONDARIES'])
          .default('ALL')
          .exactOptional()
          .openapi({
            param: {
              description:
                "Members of the shard whose readings are averaged into the shard's series.",
              in: 'query',
              name: 'nodeType',
              schema: { default: 'ALL', enum: ['ALL', 'PRIMARIES', 'SECONDARIES'], type: 'string' },
              required: false,
            },
          }),
      }),
    },
    responses: {
      200: {
        description: 'OK',
        content: {
          'application/vnd.atlas.2025-03-12+json': { schema: ShardMeasurementsResponseSchema },
        },
        headers: z.object({
          'RateLimit-Limit': HeaderRateLimitLimitHeaderSchema,
          'RateLimit-Remaining': HeaderRateLimitRemainingHeaderSchema,
        }),
      },
      400: BadRequestResponse,
      401: UnauthorizedResponse,
      403: ForbiddenResponse,
      404: NotFoundResponse,
      429: TooManyRequestsResponse,
      500: InternalServerErrorResponse,
    },
  })

