export const getApiAtlasV2GroupsGroupIdDataFederationTenantNameQueryLogsGzRoute = createRoute({
  method: 'get',
  path: '/api/atlas/v2/groups/{groupId}/dataFederation/{tenantName}/queryLogs.gz',
  tags: ['Data Federation'],
  summary: 'Download Query Logs for One Federated Database Instance',
  description:
    'Downloads the query logs for the specified federated database instance. The API does not support direct calls with the json response schema. You must request a gzip response schema using an accept header of the format: `Accept: application/vnd.atlas.YYYY-MM-DD+gzip`.',
  operationId: 'downloadGroupDataFederationQueryLogs',
  request: {
    params: z.object({
      groupId: GroupIdParamsSchema,
      tenantName: z
        .string()
        .openapi({
          param: {
            description:
              'Human-readable label that identifies the federated database instance for which you want to download query logs.',
            in: 'path',
            name: 'tenantName',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      endDate: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description:
              'Timestamp that specifies the end point for the range of log messages to download.  MongoDB Cloud expresses this timestamp in the number of seconds that have elapsed since the UNIX epoch.',
            in: 'query',
            name: 'endDate',
            schema: {
              example: 1636481348,
              format: 'int64',
              pattern: '1199145600',
              type: 'integer',
            },
            required: false,
          },
          example: 1636481348,
        }),
      startDate: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description:
              'Timestamp that specifies the starting point for the range of log messages to download. MongoDB Cloud expresses this timestamp in the number of seconds that have elapsed since the UNIX epoch.',
            in: 'query',
            name: 'startDate',
            schema: {
              example: 1636466948,
              format: 'int64',
              pattern: '1199145600',
              type: 'integer',
            },
            required: false,
          },
          example: 1636466948,
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/vnd.atlas.2023-01-01+gzip': {
          schema: z
            .file()
            .openapi({
              type: 'string',
              format: 'binary',
              description: 'Compressed archive labeled `queryLogs.gz` downloads',
            }),
        },
      },
      headers: z.object({
        'RateLimit-Limit': HeaderRateLimitLimitHeaderSchema,
        'RateLimit-Remaining': HeaderRateLimitRemainingHeaderSchema,
      }),
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    409: ConflictResponse,
    429: TooManyRequestsResponse,
    500: InternalServerErrorResponse,
  },
})

