export const getApiAtlasV2GroupsGroupIdDbAccessHistoryClustersClusterNameRoute = createRoute({
  method: 'get',
  path: '/api/atlas/v2/groups/{groupId}/dbAccessHistory/clusters/{clusterName}',
  tags: ['Access Tracking'],
  summary: 'Return Database Access History for One Cluster by Cluster Name',
  description:
    "Returns the access logs of one cluster identified by the cluster's name. Access logs contain a list of authentication requests made against your cluster. You can't use this feature on tenant-tier clusters (M0, M2, M5).",
  externalDocs: {
    description: 'Database Access History',
    url: 'https://docs.atlas.mongodb.com/access-tracking/',
  },
  operationId: 'getGroupDbAccessHistoryCluster',
  request: {
    query: z.object({
      envelope: EnvelopeParamsSchema,
      pretty: PrettyParamsSchema,
      authResult: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Flag that indicates whether the response returns the successful authentication attempts only.',
            in: 'query',
            name: 'authResult',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      end: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1199145600000n))
        .exactOptional()
        .openapi({
          param: {
            description:
              'Date and time when to stop retrieving database history. If you specify **end**, you must also specify **start**. This parameter uses UNIX epoch time in milliseconds.',
            in: 'query',
            name: 'end',
            schema: { format: 'int64', minimum: 1199145600000, type: 'integer' },
            required: false,
          },
        }),
      ipAddress: z
        .string()
        .regex(/^((25[0-5]|(2[0-4]|1\d|[1-9]|)\d)(\.(?!$)|$)){4}|([0-9a-f]{1,4}:){7}[0-9a-f]{1,4}$/)
        .exactOptional()
        .openapi({
          param: {
            description:
              'One Internet Protocol address that attempted to authenticate with the database.',
            in: 'query',
            name: 'ipAddress',
            schema: {
              pattern:
                '^((25[0-5]|(2[0-4]|1\\d|[1-9]|)\\d)(\\.(?!$)|$)){4}|([0-9a-f]{1,4}:){7}[0-9a-f]{1,4}$',
              type: 'string',
            },
            required: false,
          },
        }),
      nLogs: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(0).max(20000),
        )
        .default(20000)
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum number of lines from the log to return.',
            in: 'query',
            name: 'nLogs',
            schema: {
              default: 20000,
              format: 'int32',
              maximum: 20000,
              minimum: 0,
              type: 'integer',
            },
            required: false,
          },
        }),
      start: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1199145600000n))
        .exactOptional()
        .openapi({
          param: {
            description:
              'Date and time when MongoDB Cloud begins retrieving database history. If you specify **start**, you must also specify **end**. This parameter uses UNIX epoch time in milliseconds.',
            in: 'query',
            name: 'start',
            schema: { format: 'int64', minimum: 1199145600000, type: 'integer' },
            required: false,
          },
        }),
    }),
    params: z.object({
      groupId: GroupIdParamsSchema,
      clusterName: z
        .string()
        .regex(/^[a-zA-Z0-9][a-zA-Z0-9-]*$/)
        .openapi({
          param: {
            description: 'Human-readable label that identifies the cluster.',
            in: 'path',
            name: 'clusterName',
            required: true,
            schema: { pattern: '^[a-zA-Z0-9][a-zA-Z0-9-]*$', type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: { 'application/vnd.atlas.2023-01-01+json': { schema: MongoDBAccessLogsListSchema } },
      headers: z.object({
        'RateLimit-Limit': HeaderRateLimitLimitHeaderSchema,
        'RateLimit-Remaining': HeaderRateLimitRemainingHeaderSchema,
      }),
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: InternalServerErrorResponse,
  },
})

