export const getApiAtlasV2GroupsGroupIdMongoDBVersionsRoute = createRoute({
  method: 'get',
  path: '/api/atlas/v2/groups/{groupId}/mongoDBVersions',
  tags: ['Projects'],
  summary: 'Return All Available MongoDB LTS Versions for Clusters in One Project',
  description:
    'Returns the MongoDB Long Term Support Major Versions available to new clusters in this project.',
  operationId: 'getGroupMongoDbVersions',
  request: {
    query: z.object({
      envelope: EnvelopeParamsSchema,
      pretty: PrettyParamsSchema,
      cloudProvider: z
        .enum(['AWS', 'AZURE', 'GCP', 'TENANT'])
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter results to only one cloud provider.',
            in: 'query',
            name: 'cloudProvider',
            schema: { enum: ['AWS', 'AZURE', 'GCP', 'TENANT'], type: 'string' },
            required: false,
          },
        }),
      instanceSize: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter results to only one instance size.',
            in: 'query',
            name: 'instanceSize',
            schema: { example: 'M10', type: 'string' },
            required: false,
          },
          example: 'M10',
        }),
      defaultStatus: z
        .literal('DEFAULT')
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter results to only the default values per tier. This value must be DEFAULT.',
            in: 'query',
            name: 'defaultStatus',
            schema: { enum: ['DEFAULT'], type: 'string' },
            required: false,
          },
        }),
      itemsPerPage: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n))
        .default(100n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Number of items that the response returns per page.',
            in: 'query',
            name: 'itemsPerPage',
            schema: { default: 100, example: 100, format: 'int64', minimum: 1, type: 'integer' },
            required: false,
          },
          example: 100,
        }),
      pageNum: PageNumParamsSchema,
    }),
    params: z.object({ groupId: GroupIdParamsSchema }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/vnd.atlas.2023-01-01+json': { schema: PaginatedAvailableVersionViewSchema },
      },
      headers: z.object({
        'RateLimit-Limit': HeaderRateLimitLimitHeaderSchema,
        'RateLimit-Remaining': HeaderRateLimitRemainingHeaderSchema,
      }),
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    409: ConflictResponse,
    429: TooManyRequestsResponse,
    500: InternalServerErrorResponse,
  },
})

