export const getApiAtlasV2GroupsGroupIdProcessesProcessIdDatabaseNameCollectionNameCollStatsMeasurementsRoute =
  createRoute({
    method: 'get',
    path: '/api/atlas/v2/groups/{groupId}/processes/{processId}/{databaseName}/{collectionName}/collStats/measurements',
    tags: ['Collection Level Metrics'],
    summary: 'Return Host-Level Query Latency',
    description:
      'Get a list of the Coll Stats Latency process-level measurements for the given namespace.',
    operationId: 'listGroupProcessCollStatMeasurements',
    request: {
      params: z.object({
        groupId: GroupIdParamsSchema,
        processId: ProcessIdParamsSchema,
        databaseName: DatabaseNameParamsSchema,
        collectionName: CollectionNameParamsSchema,
      }),
      query: z.object({
        envelope: EnvelopeParamsSchema,
        metrics: z
          .preprocess(
            (val) => (val === undefined || Array.isArray(val) ? val : [val]),
            z
              .array(
                z
                  .enum([
                    'READS_OPS',
                    'READS_LATENCY',
                    'AVERAGE_READS_LATENCY',
                    'READS_P50_VALUE',
                    'READS_P95_VALUE',
                    'READS_P99_VALUE',
                    'WRITES_OPS',
                    'WRITES_LATENCY',
                    'AVERAGE_WRITES_LATENCY',
                    'WRITES_P50_VALUE',
                    'WRITES_P95_VALUE',
                    'WRITES_P99_VALUE',
                    'COMMANDS_OPS',
                    'COMMANDS_LATENCY',
                    'AVERAGE_COMMANDS_LATENCY',
                    'COMMANDS_P50_VALUE',
                    'COMMANDS_P95_VALUE',
                    'COMMANDS_P99_VALUE',
                    'TOTAL_OPS',
                    'TOTAL_LATENCY',
                    'AVERAGE_TOTAL_OPS_LATENCY',
                    'TOTAL_OPS_P50_VALUE',
                    'TOTAL_OPS_P95_VALUE',
                    'TOTAL_OPS_P99_VALUE',
                  ])
                  .openapi({ description: 'Metric requested for the given process' }),
              )
              .superRefine((items, ctx) => {
                const seen = new Map()
                for (const [i, val] of items.entries()) {
                  const key = JSON.stringify(val)
                  if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                  else seen.set(key, i)
                }
              }),
          )
          .exactOptional()
          .openapi({
            param: {
              description:
                "List that contains the metrics that you want to retrieve for the associated data series. If you don't set this parameter, this resource returns data series for all Coll Stats Latency metrics.",
              in: 'query',
              name: 'metrics',
              schema: {
                items: {
                  description: 'Metric requested for the given process',
                  enum: [
                    'READS_OPS',
                    'READS_LATENCY',
                    'AVERAGE_READS_LATENCY',
                    'READS_P50_VALUE',
                    'READS_P95_VALUE',
                    'READS_P99_VALUE',
                    'WRITES_OPS',
                    'WRITES_LATENCY',
                    'AVERAGE_WRITES_LATENCY',
                    'WRITES_P50_VALUE',
                    'WRITES_P95_VALUE',
                    'WRITES_P99_VALUE',
                    'COMMANDS_OPS',
                    'COMMANDS_LATENCY',
                    'AVERAGE_COMMANDS_LATENCY',
                    'COMMANDS_P50_VALUE',
                    'COMMANDS_P95_VALUE',
                    'COMMANDS_P99_VALUE',
                    'TOTAL_OPS',
                    'TOTAL_LATENCY',
                    'AVERAGE_TOTAL_OPS_LATENCY',
                    'TOTAL_OPS_P50_VALUE',
                    'TOTAL_OPS_P95_VALUE',
                    'TOTAL_OPS_P99_VALUE',
                  ],
                  type: 'string',
                },
                type: 'array',
                uniqueItems: true,
              },
              required: false,
            },
          }),
        start: StartParamsSchema,
        end: EndParamsSchema,
        period: PeriodParamsSchema,
      }),
    },
    responses: {
      200: {
        description: 'OK',
        content: {
          'application/vnd.atlas.2023-11-15+json': {
            schema: MeasurementsCollStatsLatencyHostSchema,
          },
        },
        headers: z.object({
          'RateLimit-Limit': HeaderRateLimitLimitHeaderSchema,
          'RateLimit-Remaining': HeaderRateLimitRemainingHeaderSchema,
        }),
      },
      400: BadRequestResponse,
      401: UnauthorizedResponse,
      403: ForbiddenResponse,
      404: NotFoundResponse,
      429: TooManyRequestsResponse,
      500: InternalServerErrorResponse,
    },
  })

