export const getApiAtlasV2GroupsGroupIdStreamsTenantNameDownloadOperationalLogsRoute = createRoute({
  method: 'get',
  path: '/api/atlas/v2/groups/{groupId}/streams/{tenantName}:downloadOperationalLogs',
  tags: ['Streams'],
  summary: 'Download Operational Logs for One Atlas Stream Processing Workspace',
  description:
    'Downloads the operational logs for the specified Atlas Streams Processing workspace or stream processor. By default, logs cover periods of 30 days. The API does not support direct calls with the json response schema. You must request a gzip response schema using an accept header of the format: "Accept: application/vnd.atlas.2025-03-12+gzip".',
  operationId: 'downloadGroupStreamOperationalLogs',
  request: {
    query: z.object({
      envelope: EnvelopeParamsSchema,
      endDate: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description:
              'Timestamp that specifies the end point for the range of log messages to download.  MongoDB Cloud expresses this timestamp in the number of seconds that have elapsed since the UNIX epoch.',
            in: 'query',
            name: 'endDate',
            schema: {
              example: 1636481348,
              format: 'int64',
              pattern: '1199145600',
              type: 'integer',
            },
            required: false,
          },
          example: 1636481348,
        }),
      startDate: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description:
              'Timestamp that specifies the starting point for the range of log messages to download. MongoDB Cloud expresses this timestamp in the number of seconds that have elapsed since the UNIX epoch.',
            in: 'query',
            name: 'startDate',
            schema: {
              example: 1636466948,
              format: 'int64',
              pattern: '1199145600',
              type: 'integer',
            },
            required: false,
          },
          example: 1636466948,
        }),
      spName: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Name of the stream processor to download logs for. An empty string will download logs for all stream processors in the workspace.',
            in: 'query',
            name: 'spName',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
    params: z.object({
      groupId: GroupIdParamsSchema,
      tenantName: z
        .string()
        .openapi({
          param: {
            description: 'Label that identifies the stream workspace.',
            in: 'path',
            name: 'tenantName',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/vnd.atlas.2025-03-12+gzip': {
          schema: z
            .file()
            .openapi({
              type: 'string',
              format: 'binary',
              description:
                'Compressed archive labeled `[tenantName]_[spName]_[startTime]_[endTime]_queries.gz` downloads',
              readOnly: true,
            }),
        },
      },
      headers: z.object({
        'RateLimit-Limit': HeaderRateLimitLimitHeaderSchema,
        'RateLimit-Remaining': HeaderRateLimitRemainingHeaderSchema,
      }),
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    409: ConflictResponse,
    429: TooManyRequestsResponse,
    500: InternalServerErrorResponse,
  },
})

