export const getApiAtlasV2OrgsOrgIdAssociatedInvoicesRoute = createRoute({
  method: 'get',
  path: '/api/atlas/v2/orgs/{orgId}/associatedInvoices',
  tags: ['Invoices'],
  summary: 'Return Associated Invoices',
  description:
    'Returns a list of invoice IDs for the specified organization and month/year. Optionally includes invoices from linked organizations.',
  operationId: 'getOrgAssociatedInvoices',
  request: {
    params: z.object({ orgId: OrgIdParamsSchema }),
    query: z.object({
      month: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n).max(12n))
        .exactOptional()
        .openapi({
          param: {
            description:
              'The month for which to retrieve invoices (1-12). Defaults to current month.',
            in: 'query',
            name: 'month',
            schema: { format: 'int64', maximum: 12, minimum: 1, type: 'integer' },
            required: false,
          },
        }),
      year: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(2000n))
        .exactOptional()
        .openapi({
          param: {
            description: 'The year for which to retrieve invoices. Defaults to current year.',
            in: 'query',
            name: 'year',
            schema: { format: 'int64', minimum: 2000, type: 'integer' },
            required: false,
          },
        }),
      includeLinkedOrgs: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Whether to include invoices from linked organizations. Defaults to false.',
            in: 'query',
            name: 'includeLinkedOrgs',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Associated invoices retrieved successfully',
      content: {
        'application/vnd.atlas.2025-03-12+json': { schema: OrgAssociatedInvoiceResponseSchema },
        'application/vnd.atlas.preview+json': { schema: OrgAssociatedInvoiceResponseSchema },
      },
      headers: z.object({
        'RateLimit-Limit': HeaderRateLimitLimitHeaderSchema,
        'RateLimit-Remaining': HeaderRateLimitRemainingHeaderSchema,
      }),
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: InternalServerErrorResponse,
  },
})

