export const getApiAtlasV2RateLimitsRoute = createRoute({
  method: 'get',
  path: '/api/atlas/v2/rateLimits',
  tags: ['Rate Limiting'],
  summary: 'Return All Rate Limits',
  description: 'Get all rate limits for all v2 Atlas Administration API endpoint sets.',
  operationId: 'listRateLimits',
  request: {
    query: z.object({
      itemsPerPage: ItemsPerPageParamsSchema,
      pageNum: PageNumParamsSchema,
      pretty: PrettyParamsSchema,
      envelope: EnvelopeParamsSchema,
      groupId: z
        .string()
        .regex(/^([a-f0-9]{24})$/)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Unique 24-hexadecimal digit string that identifies the Atlas Project to request rate limits for. When this parameter is provided, only group scoped endpoint sets are returned and the limits returned are applicable to the specified project. The requesting user must have the Project Read Only role for the specified project.',
            in: 'query',
            name: 'groupId',
            schema: {
              example: '32b6e34b3d91647abb20e7b8',
              pattern: '^([a-f0-9]{24})$',
              type: 'string',
            },
            required: false,
          },
          example: '32b6e34b3d91647abb20e7b8',
        }),
      orgId: z
        .string()
        .regex(/^([a-f0-9]{24})$/)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Unique 24-hexadecimal digit string that identifies the Atlas Organization to request rate limits for. When this parameter is provided, only organization scoped endpoint sets are returned and the limits returned are applicable to the specified organization. The requesting user must have the Organization Read Only role for the specified organization.',
            in: 'query',
            name: 'orgId',
            schema: {
              example: '32b6e34b3d91647abb20e7b8',
              pattern: '^([a-f0-9]{24})$',
              type: 'string',
            },
            required: false,
          },
          example: '32b6e34b3d91647abb20e7b8',
        }),
      userId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'A string that identifies the Atlas user to request rate limits for. The ID can for example be the Service Account Client ID or the API Public Key. When this parameter is provided, only user scoped endpoint sets are returned and the limits returned are applicable to the specified user. The requesting user must be the same as the specified user.',
            in: 'query',
            name: 'userId',
            schema: { example: 'mdb_sa_id_1234567890abcdef12345678', type: 'string' },
            required: false,
          },
          example: 'mdb_sa_id_1234567890abcdef12345678',
        }),
      ipAddress: z
        .string()
        .regex(/^((25[0-5]|(2[0-4]|1\d|[1-9]|)\d)(\.(?!$)|$)){4}|([0-9a-f]{1,4}:){7}[0-9a-f]{1,4}$/)
        .exactOptional()
        .openapi({
          param: {
            description:
              'An IP address to request rate limits for. When this parameter is provided, only IP scoped endpoint sets are returned and the limits returned are applicable to the specified IP address. The requesting user must have the same IP address as the one provided in the request.',
            in: 'query',
            name: 'ipAddress',
            schema: {
              example: '127.0.0.1',
              pattern:
                '^((25[0-5]|(2[0-4]|1\\d|[1-9]|)\\d)(\\.(?!$)|$)){4}|([0-9a-f]{1,4}:){7}[0-9a-f]{1,4}$',
              type: 'string',
            },
            required: false,
          },
          example: '127.0.0.1',
        }),
      name: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filters the returned endpoint sets by the provided endpoint set name. Multiple names may be provided, for example `/rateLimits?name=Name1&name=Name2`. For names that use spaces, replace the space with its URL-encoded value (`%20`).',
            in: 'query',
            name: 'name',
            schema: { example: 'Rate Limits Inspection', type: 'string' },
            required: false,
          },
          example: 'Rate Limits Inspection',
        }),
      endpointPath: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filters the returned endpoint sets by the provided endpoint path. Multiple paths may be provided, for example `/rateLimits?endpointPath=%2Fapi%2Fatlas%2Fv2%2Fclusters&endpointPath=%2Fapi%2Fatlas%2Fv2%2Fgroups%2F%7BgroupId%7D%2F`. Replace `/`, `{` and `}` with their URL-encoded values (`%2F`, `%7B` and `%7D` respectively).',
            in: 'query',
            name: 'endpointPath',
            schema: { example: '/api/atlas/v2/clusters', type: 'string' },
            required: false,
          },
          example: '/api/atlas/v2/clusters',
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/vnd.atlas.2025-03-12+json': { schema: PaginatedRateLimitEndpointSetsSchema },
      },
      headers: z.object({
        'RateLimit-Limit': HeaderRateLimitLimitHeaderSchema,
        'RateLimit-Remaining': HeaderRateLimitRemainingHeaderSchema,
      }),
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    429: TooManyRequestsResponse,
    500: InternalServerErrorResponse,
  },
})

